clive.reference_solution:
#include <stdio.h>

int getScore(int n)
{
    int i;
    int score = 0;

    for (i = 1; i <= n; i++)
    {
        if (i % 3 == 0 && i % 7 == 0)
            score = score + 10;
        else if (i % 7 == 0)
            score = score + 7;
        else if (i % 3 == 0)
            score = score + 3;
        else
            score = score + 1;
    }

    return score;
}

