int isValidID(int id)
{
    int temp, digit, pos;
    int oddCount = 0, oddPosSum = 0, evenPosSum = 0;

    /* must have exactly 8 digits, and the first digit cannot be 0 */
    if (id < 10000000 || id > 99999999)
        return 0;

    temp = id;
    for (pos = 1; pos <= 8; pos++)
    {
        digit = temp % 10;

        if (digit % 2 == 1)
            oddCount = oddCount + 1;

        if (pos % 2 == 1)
            oddPosSum = oddPosSum + digit;
        else
            evenPosSum = evenPosSum + digit;

        temp = temp / 10;
    }

    if (oddCount >= 3 && oddPosSum == evenPosSum)
        return 1;
    else
        return 0;
}

