#include <stdio.h>

#define MEAL_PRICE 30
#define DRINK_PRICE 20

int countCombinations(int budget)
{
    int meals, drinks;
    int count = 0;

    /* try every number of meals and drinks, starting at 1 each */
    for (meals = 1; meals * MEAL_PRICE <= budget; meals++)
    {
        for (drinks = 1; drinks * DRINK_PRICE <= budget; drinks++)
        {
            if (meals * MEAL_PRICE + drinks * DRINK_PRICE <= budget)
                count = count + 1;
        }
    }

    return count;
}
